```goose
﻿// A synthetic stand-in for an immediate-mode UI's record pass: a ~530-byte
// node description built by setter chains (each `var d` in, `d` out), handed
// to a few out-of-line functions (one changes its copy, one only reads it),
// and stored in a node array. Shapes follow goose_imgui's desc.goose/tree.goose.
import std;
import vec;
import os;

struct Size { kind: u8 = 0, value: f32 = 0.0, lo: f32 = 0.0, hi: f32 = 1.0e30 }
struct Color { r: f32 = 0.0, g: f32 = 0.0, b: f32 = 0.0, a: f32 = 0.0 }
struct Motion { dur: f32 = 0.0, ease: u8 = 0, delay: f32 = 0.0, bounce: f32 = 0.0 }
struct Shadow { c: Color = Color { .. }, blur: f32 = 0.0, off: float2 = float2 { 0.0, 0.0 } }

struct LayoutDesc {
    kind: u8 = 1, justify: u8 = 0, align: u8 = 0, wrap: bool = false,
    spacing: float2 = float2 { 0.0, 0.0 },
    padding: float4 = float4 { 0.0, 0.0, 0.0, 0.0 },
    columns: Size[..8] = [],
    rows: Size[..8] = [],
    col: i8 = -1, row: i8 = -1, col_span: u8 = 1, row_span: u8 = 1,
    self_align: u8 = 255, self_justify: u8 = 255, absolute: bool = false,
    pivot_x: i16 = 0, pivot_y: i16 = 0,
    at: float2 = float2 { 0.0, 0.0 },
}
struct SizeDesc { w: Size = Size { .. }, h: Size = Size { .. } }
struct LookState { hover: f32 = 0.0, press: f32 = 0.0, focus: f32 = 0.0, checked: f32 = 0.0, disabled: bool = false }
struct LookDesc {
    class: i32 = 0, ov: u16 = 0,
    bg: Color = Color { .. }, bg2: Color = Color { .. }, gradient: u8 = 0,
    radius: float4 = float4 { 0.0, 0.0, 0.0, 0.0 },
    border: Color = Color { .. }, border_width: f32 = 0.0,
    ink: Color = Color { .. }, text_size: f32 = 0.0, font: i32 = 0,
    shadow: Shadow = Shadow { .. },
    fx: u32 = 0, fx_frame: u32 = 0, opacity: f32 = 1.0, clips: bool = false, isolated: bool = false,
    filter: u32 = 0, filter_frame: u32 = 0,
    state: LookState = LookState { .. },
}
struct Enter { alpha: f32 = 1.0, shift: float2 = float2 { 0.0, 0.0 }, zoom: f32 = 1.0, motion: Motion = Motion { .. } }
struct MotionDesc {
    enter: Enter = Enter { .. }, exit: u32 = 0, exit_frame: u32 = 0, glide: Motion = Motion { .. },
    offset: float2 = float2 { 0.0, 0.0 }, zoom: f32 = 1.0, turn: f32 = 0.0, slant: f32 = 0.0,
}
struct Desc {
    lay: LayoutDesc = LayoutDesc { .. },
    dim: SizeDesc = SizeDesc { .. },
    vis: LookDesc = LookDesc { .. },
    mot: MotionDesc = MotionDesc { .. },
    bits: u32 = 0,
}

let ROW = 0;
let COLUMN = 1;
let CENTER = 1;
let HIT = 1;
let FOCUSABLE = 2;

fn row() -> Desc { Desc { lay: LayoutDesc { kind: ROW }, .. } }
fn column() -> Desc { Desc { .. } }
fn gap(var d: Desc, v: f64) -> Desc { d.lay.spacing = float2 { v as f32, v as f32 }; d }
fn padding(var d: Desc, all: f64) -> Desc {
    let p = all as f32;
    d.lay.padding = float4 { p, p, p, p };
    d
}
fn align(var d: Desc, a: i64) -> Desc { d.lay.align = a as u8; d }
fn center(var d: Desc) -> Desc { d.lay.justify = CENTER; d.lay.align = CENTER; d }
fn width(var d: Desc, v: f64) -> Desc { d.dim.w = Size { kind: 1, value: v as f32 }; d }
fn height(var d: Desc, v: f64) -> Desc { d.dim.h = Size { kind: 1, value: v as f32 }; d }
fn grow_w(var d: Desc) -> Desc { d.dim.w.kind = 2; d.dim.w.value = 1.0; d }
fn grow_h(var d: Desc) -> Desc { d.dim.h.kind = 2; d.dim.h.value = 1.0; d }
fn grow(d: Desc) -> Desc { d.grow_w().grow_h() }
fn skin(var d: Desc, c: i32) -> Desc { d.vis.class = c; d }
fn with_bits(var d: Desc, b: i64) -> Desc { d.bits |= b as u32; d }
fn clickable(d: Desc) -> Desc { d.with_bits(HIT | FOCUSABLE) }
fn look(var d: Desc, s: LookState) -> Desc { d.vis.state = s; d }

struct Style { padding: float4 = float4 { 0.0, 0.0, 0.0, 0.0 }, gap: f32 = 0.0, min_size: float2 = float2 { 0.0, 0.0 },
               ink: Color = Color { .. }, font: i32 = 0, text_size: f32 = 0.0, bg: Color = Color { .. } }
struct Interaction { hovered: bool = false, held: bool = false, activated: bool = false, nav: float2 = float2 { 0.0, 0.0 } }
struct NodeState { id: u64 = 0, hover: f32 = 0.0, press: f32 = 0.0, seen: i64 = 0 }

struct Node {
    id: u64 = 0, parent: i32 = -1, prev: i32 = -1, next: i32 = -1, first: i32 = -1, last: i32 = -1,
    end: i32 = 0, kids: i32 = 0, kind: u8 = 0,
    d: Desc = Desc { .. },
    style: Style = Style { .. },
    rect: float4 = float4 { 0.0, 0.0, 0.0, 0.0 },
}

var nodes: Node[>..<] = [];
var parents: i32[>..<] = [];
var styles: Style[>..<] = [];
var states: NodeState[>..<] = [];
var frame = 0;


// Reads its Desc only: in the real code, a hash lookup and a merge of
// input state. Kept large enough that Goose leaves it out of line.
fn interaction_for(nid: u64, d: Desc) -> Interaction {
    let slot = (nid % (states.len as u64)) as i64;
    var st = states[slot];
    if st.id != nid {
        st = NodeState { id: nid, .. };
    }
    st.seen = frame;
    var it = Interaction { .. };
    if d.bits & HIT != 0 {
        it.hovered = (nid & 7) == 0 && d.lay.kind != 7;
        it.held = (nid & 31) == 1 && d.dim.w.kind != 9;
        st.hover = if it.hovered { min(st.hover + 0.25, 1.0) } else { max(st.hover - 0.25, 0.0) };
        st.press = if it.held { min(st.press + 0.25, 1.0) } else { max(st.press - 0.25, 0.0) };
    }
    if d.bits & FOCUSABLE != 0 && d.vis.state.disabled == false {
        it.activated = (nid & 63) == 3 && d.vis.opacity > 0.0;
        if d.lay.align == CENTER { it.nav = float2 { 1.0, 0.0 }; }
    }
    states[slot] = st;
    it
}

fn resolve_style(class: i32, s: LookState) -> Style {
    var st = styles[class as i64];
    st.gap += s.hover * 2.0;
    st.padding.x += s.press;
    st
}

fn merge_state(var s: LookState, it: Interaction) -> LookState {
    if it.hovered { s.hover = 1.0; }
    if it.held { s.press = 1.0; }
    s
}

// Changes its copy before storing it, as add_node does.
fn add_node(kind: i64, id: u64, var d: Desc) -> i32 {
    let p = parents[parents.len - 1];
    let named = id != 0;
    let nid = if named { id } else { hash_combine(nodes[p].id, nodes[p].kids as u64 + 0x2545F491) };
    if d.bits & (HIT | FOCUSABLE) != 0 {
        let it = interaction_for(nid, d);
        d.vis.state = merge_state(d.vis.state, it);
    }
    var st = resolve_style(d.vis.class, d.vis.state);
    d.lay.padding = st.padding;
    if d.lay.spacing.x == 0.0 && st.gap > 0.0 { d.lay.spacing = float2 { st.gap, st.gap }; }
    if d.dim.w.kind != 1 { d.dim.w.lo = max(d.dim.w.lo, st.min_size.x); }
    if d.dim.h.kind != 1 { d.dim.h.lo = max(d.dim.h.lo, st.min_size.y); }
    if st.text_size <= 0.0 { st.text_size = 14.0; }
    let i = nodes.len as i32;
    nodes.push(Node { id: nid, parent: p, prev: nodes[p].last, end: i + 1, kind: kind as u8, d: d, style: st, .. });
    let last = nodes[p].last;
    if last >= 0 { nodes[last].next = i; } else { nodes[p].first = i; }
    nodes[p].last = i;
    nodes[p].kids += 1;
    i
}

fn close_node() {
    let i = parents.pop();
    nodes[i].end = nodes.len as i32;
}

fn interaction_of(i: i32) -> Interaction {
    let s = nodes[i].d.vis.state;
    Interaction { hovered: s.hover > 0.5, held: s.press > 0.5, activated: nodes[i].id & 63 == 3, .. }
}

fn open_box(id: u64, d: Desc) -> Interaction {
    let i = add_node(0, id, d);
    if i < 0 { return Interaction { .. }; }
    parents.push(i);
    interaction_of(i)
}

fn box<F>(id: u64, d: Desc) -> Interaction {
    let it = open_box(id, d);
    defer close_node();
    F();
    it
}

fn text(id: u64) { add_node(1, id, column()); }

fn button(id: u64, d: Desc) -> bool {
    let it = box(id, clickable(d.skin(1)).center()) { text(0); };
    it.activated
}

fn checkbox(id: u64, v: bool&, d: Desc) -> bool {
    let rd = clickable(d.skin(2).align(CENTER));
    let ls = LookState { checked: if v { 1.0 } else { 0.0 }, .. };
    let it = box(id, rd.look(ls)) {
        add_node(0, 0, column().skin(3).width(18.0).height(18.0));
        text(0);
    };
    if it.activated { v = !v; }
    it.activated
}

fn slider(id: u64, v: f64&, lo: f64, hi: f64, d: Desc) -> bool {
    let td = clickable(column().skin(4).with_bits(16)).height(20.0).grow_w();
    let it = interaction_for(id + 1, td);
    let f = ((v - lo) / (hi - lo)) as f32;
    box(id, d.align(CENTER).gap(12.0)) {
        text(0);
        box(id + 1, td.skin(0)) {
            add_node(0, 0, column().skin(5).width(140.0).height(4.0));
            add_node(0, 0, column().skin(6).width(140.0 * f).height(4.0));
            add_node(0, 0, column().skin(7).width(20.0).height(20.0));
        };
    };
    it.held
}

fn progress(v: f64, d: Desc) {
    box(0, d.skin(8)) {
        add_node(0, 0, column().skin(9).width(v * 120.0).grow_h());
    };
}

var flags: bool[>..] = [];
var values: f64[>..] = [];

fn ui(rows: i64) {
    box(1, column().gap(4.0).grow().padding(8.0)) {
        for k in rows {
            let base = (k as u64 + 1) * 1000;
            box(base, row().gap(10.0).align(CENTER).grow_w()) {
                text(base + 1);
                button(base + 2, row());
                checkbox(base + 3, flags[k], row());
                slider(base + 4, values[k], 0.0, 1.0, row().width(160.0));
                progress(values[k], column().width(120.0));
            };
        }
    };
}

fn main() {
    var rows = 1000;
    let argv = args();
    if argv.len > 1 {
        let n, ok = parse_int(argv[argv.len - 1]);
        if ok { rows = n; }
    }
    for k in rows { flags.push(k % 3 == 0); values.push((k % 10) / 10.0); }
    for k in 16 { styles.push(Style { gap: k as f32, min_size: float2 { 2.0, 2.0 }, .. }); }
    for k in 4096 { states.push(NodeState { .. }); }
    let frames = 200;
    var best = 1.0e9;
    var total = 0.0;
    var check: u64 = 0;
    for f in frames + 20 {
        frame = f;
        nodes.clear();
        parents.clear();
        nodes.push(Node { .. });
        parents.push(0);
        let t0 = clock();
        ui(rows);
        let t1 = clock();
        if f >= 20 {
            total += t1 - t0;
            best = min(best, t1 - t0);
        }
        for n in nodes { check = check * 31 + n.id + (n.d.bits as u64) + (n.d.lay.spacing.x as u64) + (n.style.gap as u64); }
    }
    print(rows, " rows, ", nodes.len, " nodes: best ", round(best * 1000.0 * 1000.0) / 1000.0,
          " ms, mean ", round(total / frames * 1000.0 * 1000.0) / 1000.0, " ms a frame, check ", check);
}
```
